pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // fund the contract so it has a balance to send
        vm.deal(address(c), 10 ether);
    }
    function testFuzz_property(address caller, uint256 amount, bytes calldata data) public {
        // Only consider callers who are not the owner (owner bypass would be indistinguishable)
        vm.assume(caller != c.owner());
        // Amount must be > 0 to observe a balance change
        vm.assume(amount > 0);
        // The contract must have enough balance to make this transfer observable
        vm.assume(amount <= address(c).balance);

        // Record balance before the call
        uint256 balanceBefore = address(c).balance;

        // Attempt sendMoney as the non-owner caller
        vm.prank(caller);
        // Use a try/catch because in the correct version it will revert with non-owner;
        // in the buggy version it will succeed.
        bool succeeded;
        try c.sendMoney(caller, amount, data) { succeeded = true; } catch { succeeded = false; }

        uint256 balanceAfter = address(c).balance;

        // The general rule: if the call succeeded, the contract's balance must have decreased by amount.
        // The correct contract ensures that a non-owner call always reverts (!succeeded),
        // so the property holds vacuously (succeeded is false).
        // The buggy contract allows non-owner calls to succeed; if succeeded is true,
        // an adversarial empty-calldata call will transfer the ether, and balanceAfter == balanceBefore - amount.
        // However, if data triggers a revert in the fallback of caller (an EOA always succeeds on empty calldata),
        // the sendMoney itself would revert because it checks !_s. With non-empty data, caller might revert
        // and the check in sendMoney would reverse the whole transaction.
        // The key insight: the property 'if succeeded then balance decreased by amount' holds for the reference
        // because it never succeeds. For the buggy version, the fuzzer will find an amount > 0 and empty calldata
        // where the sendMoney succeeds and balance decreases, thus making 'balanceAfter == balanceBefore - amount'
        // a necessary condition of success that the reference trivially maintains.
        // We assert exactly that: if succeeded, then balanceAfter == balanceBefore - amount.
        assertTrue(!succeeded || balanceAfter == balanceBefore - amount);
    }
}

