pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 initialDeposit) public {
        // Ensure we have a non-zero balance so the invariant is meaningful.
        vm.assume(initialDeposit > 0);
        // The caller must be distinct from the owner to trigger the bug.
        vm.assume(caller != c.owner());

        // Fund the contract via a deposit from the owner (or anyone) to set up a balance.
        vm.deal(address(this), initialDeposit);
        (bool fundOk, ) = address(c).call{value: initialDeposit}("");
        require(fundOk, "funding failed");

        // Record state before calling withdrawAll.
        uint256 initialBal = address(c).balance;
        uint256 initialDeposits = c.depositsCount();

        // Call withdrawAll as the fuzzed caller.
        vm.prank(caller);
        (bool withdrawOk, ) = address(c).call(abi.encodeWithSelector(C.withdrawAll.selector));

        // If the call did not revert, the invariant must hold:
        // The initial balance must equal the current balance plus the difference in depositsCount
        // (each depositCount increase corresponds to 1 wei deposited via fallback).
        if (withdrawOk) {
            uint256 finalBal = address(c).balance;
            uint256 finalDeposits = c.depositsCount();
            // Because fallback increments depositsCount on every deposit, the only way to alter
            // the contract's balance without increasing depositsCount is a withdrawal. The invariant
            // states that initial balance = current balance + (current deposits - initial deposits).
            assertTrue(initialBal == finalBal + (finalDeposits - initialDeposits));
        }
    }
}

